def get_value_at_index(arr, index):
    if not arr:
        return None  # atau bisa juga mengembalikan nilai default seperti 0 atau None
    n = len(arr)
    # Normalisasi indeks
    if index >= 0:
        normalized_index = index % n if n > 0 else 0
    else:
        normalized_index = (index % n) if n > 0 else 0
    return arr[normalized_index]

