def find_index_of_largest(lst):
    if not lst:
        return None
    return lst.index(max(lst))

# Example usage:
numbers = [1, 3, 7, 2, 5]
index = find_index_of_largest(numbers)
print(index)  # Output: 2 (index of 7, the largest number)
